# Parse times with multiple formats
def parse_time(t):
    for fmt in ["%B %d, %Y at %I:%M %p", "%Y-%m-%d %H:%M:%S", "%d %b %Y, %H:%M"]:
        try:
            return pd.to_datetime(t, format=fmt)
        except Exception:
            pass
    return pd.NaT

df['dt'] = df['time'].apply(parse_time)
